package com.medicinemanager.service;
import com.medicinemanager.dto.Requests.PeriodRequest; import com.medicinemanager.entity.*; import com.medicinemanager.exception.*; import com.medicinemanager.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class PeriodService {private final PeriodRepository r;private final AppUserRepository users;public PeriodService(PeriodRepository r,AppUserRepository u){this.r=r;users=u;}public List<Period> findAll(){return r.findAll();} public List<Period> findByUserId(UUID userId){user(userId);return r.findByUserId(userId);}public Period find(UUID id){return r.findById(id).orElseThrow(()->new NotFoundException("Period not found"));}public Period create(PeriodRequest x){return r.save(new Period(user(x.userId()),x.name().trim(),x.time()));}public Period update(UUID id,PeriodRequest x){var p=find(id);if(!p.getUser().getId().equals(x.userId()))throw new BusinessRuleException("Period owner cannot be changed");p.setName(x.name().trim());p.setTime(x.time());return r.save(p);}public void delete(UUID id){r.delete(find(id));}private AppUser user(UUID id){return users.findById(id).orElseThrow(()->new NotFoundException("User not found"));}}
